// VIOLATION: fat interface — Robot forced to implement eat() and sleep()
interface Worker {
    void work();
    void eat();
    void sleep();
}
class Robot implements Worker {
    public void work() { /* works */ }
    public void eat()  { throw new UnsupportedOperationException(); } // forced!
    public void sleep(){ throw new UnsupportedOperationException(); } // forced!
}

// ISP fix: segregated interfaces
interface Workable  { void work(); }
interface Eatable   { void eat(); }
interface Sleepable { void sleep(); }
class Robot   implements Workable { public void work() { /* works */ } }
class Human   implements Workable, Eatable, Sleepable { /* all */ }

// ISP violation: every service gets full JpaRepository even if it only reads
interface UserRepository extends JpaRepository<User, Long> { /* 30+ methods */ }

// ISP better: define read-only interface for services that only read
interface ReadOnlyUserRepository {
    Optional<User> findById(Long id);
    List<User> findByEmail(String email);
}

// Spring Data alternative: extend only what you need
interface UserRepository extends CrudRepository<User, Long> {
    // only use JpaRepository when you need paging/sorting/JPQL
}
